package de.ga36.home;
import android.os.*;import android.content.*;import android.widget.*;import java.io.*;
public final class UsbActivity extends ConsolePanel {
 final Handler ui=new Handler();TextView state,detail;boolean active;int generation;HandlerThread thread;Handler worker;
 String read(String file){try{BufferedReader r=new BufferedReader(new FileReader("/sys/class/android_usb/android0/"+file));try{String s=r.readLine();return s==null?"":s.trim();}finally{r.close();}}catch(IOException e){return "";}}
 final Runnable refresh=new Runnable(){public void run(){if(!active||worker==null)return;final int token=generation;worker.post(new Runnable(){public void run(){final String connection=read("state"),functions=read("functions");Intent usb=registerReceiver(null,new IntentFilter("android.hardware.usb.action.USB_STATE"));final boolean unlocked=usb!=null&&usb.getBooleanExtra("unlocked",false);ui.post(new Runnable(){public void run(){if(!active||generation!=token)return;state.setText(UsbControl.status(connection));detail.setText(I18n.t("Modus: ")+functions+I18n.t(" · Dateien: ")+(unlocked?I18n.t("freigegeben"):I18n.t("gesperrt"))+I18n.t("\nUSB-Datenkabel am OTG-Anschluss mit dem PC verbinden."));ui.postDelayed(refresh,1500);}});}});}};
 void mode(boolean files,boolean unlock,boolean debug){try{if(!android.provider.Settings.Global.putInt(getContentResolver(),"adb_enabled",debug?1:0))throw new IllegalStateException(I18n.t("USB-Diagnose konnte nicht aktiviert werden"));UsbControl.select(getSystemService(USB_SERVICE),files,unlock);Toast.makeText(this,files?I18n.t("Dateiübertragung angefordert"):I18n.t("Diagnosemodus angefordert"),0).show();}catch(RuntimeException e){Toast.makeText(this,I18n.t("USB konnte nicht umgeschaltet werden"),1).show();android.util.Log.e("GA36USB","MODE_REQUEST_FAILED",e);}++generation;ui.removeCallbacks(refresh);ui.postDelayed(refresh,400);}
 public void onCreate(Bundle b){super.onCreate(b);text(I18n.t("USB zum PC"),25);state=text(I18n.t("Verbindung wird geprüft …"),19);detail=text("",14);button(I18n.t("Nur Dateien · MTP freigeben"),new Runnable(){public void run(){mode(true,true,false);}});button(I18n.t("Dateien + USB-Diagnose"),new Runnable(){public void run(){mode(true,true,true);}});button(I18n.t("Nur USB-Diagnose"),new Runnable(){public void run(){mode(false,false,true);}});button(I18n.t("Zurück"),new Runnable(){public void run(){finish();}});}
 protected void onResume(){super.onResume();active=true;++generation;thread=new HandlerThread("GA36 USB status");thread.start();worker=new Handler(thread.getLooper());ui.post(refresh);}
 protected void onPause(){active=false;++generation;ui.removeCallbacksAndMessages(null);worker.removeCallbacksAndMessages(null);thread.quitSafely();worker=null;thread=null;super.onPause();}
}
